const journeys={
 nearby:[['Por perto','Abra o quadro. Cada cartão representa uma pessoa, com livros no lugar da foto.'],['Pessoa','Toque em Ana. O perfil abre como tela, sem curtir automaticamente.'],['Opinião do livro','Expanda um livro no próprio perfil. Nenhuma terceira tela é criada.'],['Voltar ao quadro','A posição do quadro permanece. Reabra a pessoa para tomar uma decisão.'],['Curtir e dar match','Se o interesse for recíproco, a confirmação oferece conversar ou continuar.'],['Conversa','Abra o chat da pessoa escolhida. A foto continua sujeita à conversa e aos dois aceites.']],
 deck:[['Para você','Veja uma pessoa por vez. Toque nas laterais para trocar o livro.'],['Perfil completo','Abra o perfil para ler a apresentação e as opiniões.'],['Voltar ao cartão','O cartão reaparece no mesmo livro.'],['Passar ou curtir','A decisão vale para a pessoa. Passar mostra a próxima; curtir pode gerar match.'],['Match','Continuar mantém a descoberta; conversar abre a thread do novo match.']],
 chat:[['Conversas','Abra Lia pela lista. A aba Conversas sempre leva à caixa.'],['Conversa com Lia','Escreva um rascunho e leia o histórico.'],['Perfil de Lia','Toque no nome. A origem registrada é esta conversa.'],['Voltar à conversa','O rascunho e a posição de leitura são preservados.'],['Voltar à caixa','O botão do cabeçalho retorna à lista, sem apagar ou encerrar o match.']]
};
const steps=document.querySelector('#steps');
function showJourney(value){steps.replaceChildren(...journeys[value].map(([title,description])=>{const li=document.createElement('li'),strong=document.createElement('strong'),p=document.createElement('p');strong.textContent=title;p.textContent=description;li.append(strong,p);return li;}));}
document.querySelector('#journey').addEventListener('change',event=>showJourney(event.target.value));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));document.querySelectorAll('figure[data-app]').forEach(figure=>{figure.hidden=button.dataset.filter!=='all'&&figure.dataset.app!==button.dataset.filter;});}));
showJourney('nearby');
